def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case. Consecutive capitals stay together (HTTPServer -> http_server)."""
    if not s:
        return ""
    result = []
    for i, ch in enumerate(s):
        if ch.isupper():
            # Determine if underscore needed
            if i > 0:
                prev = s[i-1]
                # Start of an acronym: previous is upper and next is lower
                if prev.isupper():
                    next_is_lower = i+1 < len(s) and s[i+1].islower()
                    if next_is_lower:
                        result.append("_")
                elif prev.islower() or prev.isdigit():
                    result.append("_")
            result.append(ch.lower())
        else:
            result.append(ch)
    return "".join(result)

